import cv2, numpy as np
from PIL import Image
im=cv2.imread('first_frame.png')
hsv=cv2.cvtColor(im,cv2.COLOR_BGR2HSV)
# masks named (opencv hsv)
specs={
'orange':((2,70,70),(28,255,255)),
'blue':((90,50,20),(140,255,255)),
'black':((0,0,0),(180,255,65)),
'white':((0,0,165),(180,60,255)),
'gray':((0,0,70),(180,40,190)),
}
for name,(lo,hi) in specs.items():
 m=cv2.inRange(hsv,np.array(lo),np.array(hi)); n=int((m>0).sum())
 nlab, lab, stats, cent=cv2.connectedComponentsWithStats(m)
 ids=np.argsort(stats[1:,4])[::-1][:15]+1
 print('\\n',name,'total',n)
 for i in ids:
  x,y,w,h,a=stats[i];
  if a<50: continue
  print(' ',a,'bbox',x,y,w,h,'center',np.round(cent[i],1))
